		}

		int count = 0;
		outer:
		for (int i = hills.length - 1; ; i--) {
			if (hills[i] > 0) {
				for (int j = 0; j < hills[i]; j++) {
					System.out.println(i);
					count++;
					if (count == 3) break outer;
				}
			}
		}
	}
}

