        int[] sides = { side_a, side_b, side_c };
        Arrays.sort(sides);

        int a_2 = (int)Math.pow(sides[0], 2);
        int b_2 = (int)Math.pow(sides[1], 2);
        int c_2 = (int)Math.pow(sides[2], 2);

        return a_2 + b_2 == c_2;
    }

}

