	static int gcd(int a,int b){
		int c=Math.max(a, b);
		int d=Math.min(a, b);
		while(c%d!=0){
			int e=c%d;
			c=d;
			d=e;
		}
		return d;
	}
	static int lcm(int a,int b){
		int gcd=gcd(a,b);
		int resa=a/gcd;
		int resb=b/gcd;
		int lcm=resa*resb*gcd;
		return lcm;
	}
}

