    }

    static long solveLCM (long a, long b) {
	if (a == 0 || b == 0) {
	    return 0;
	}
	long i = 1;
	long max = Math.max(a, b);
	long lcm = max * i++;
	long min = Math.min(a, b);
	while (lcm % min != 0) {
	    lcm = max * i++;
	}
	//return lcm;
	return a * b / solveGCD(a,b);
    }
}

