	public int calcGCD(int a_in, int b_in) {
		int a, b;
		if (a_in == b_in) { return a_in;
		} else if (a_in < b_in) { a = b_in; b = a_in;
		} else { a = a_in; b = b_in; }

		int r = a % b;
		if (r == 0) { return b;
		} else { return calcGCD(b, r); }
	}

