class Main {
	public static void bubble(int[] A) {
		int N = A.length;
        for(int k=0;k<N;k++) {
            System.out.print(String.format("%d%s", A[k], (k==N-1 ? "" : " ")));
        }
		System.out.println("");
		for(int i=1;i<N;i++) {
			int v = A[i];
			int j = i - 1;
			while (j >= 0 && A[j] > v) {
				A[j+1] = A[j];
				j--;
			}
			A[j+1] = v;
			for(int k=0;k<N;k++) {
				System.out.print(String.format("%d%s", A[k], (k==N-1 ? "" : " ")));
			}
			System.out.println("");
		}
	}
