        int y = Integer.parseInt(strY);

        int answer = divisor(x, y);

        System.out.println(answer);
        scan.close();
    }

    static int divisor(int x, int y) {
        if (y > x) {
            return divisor(y, x);
        }
        while (y != 0) {
            int remainder = x % y;
            x = y;
            y = remainder;
        }
        return x;
    }
}

