		Scanner br = new Scanner(System.in);
		int len;

		len = br.nextInt();
		ArrayList<Integer> arr= new ArrayList<Integer>();
		int val = 0;
		while(len > 0) {
			val = br.nextInt();
			arr.add(val);
			len --;
		}


		//invoke the computation part
		System.out.println(max_profit(arr));
		br.close();

	}

}

