Main
{
  private int swc;

  private void
  sort (
    int[ ] a
    )
  {
    int i, j;

    for ( i = 0; i < a.length; ++i )
    {
      for ( j = 1; j < a.length - i; ++j )
      {
        if ( a[ j ] < a[ j - 1 ] )
          swap ( a, j - 1, j );
      }
    }
  }

  private void
  swap (
    int[ ] a,
    int    i,
    int    j
    )
  {
    final int t = a[ i ];
    a[ i ] = a[ j ];
    a[ j ] = t;
    ++swc;
  }

  private void
  printArray (
    int[ ] a
    )
  {
    int i;

    for ( i = 0; i < a.length; ++i )
    {
      System.out.print ( a[ i ] );
