/**
1 bubbleSort(A, N) // N 個の要素を含む 0-オリジンの配列 A
2   flag = 1 // 逆の隣接要素が存在する
3   while flag
4     flag = 0
5     for j が N-1 から 1 まで
6       if A[j] < A[j-1]
7         A[j] と A[j-1] を交換
8         flag = 1

入力例 1
5
5 3 2 4 1
出力例 1
1 2 3 4 5
8
 */

import java.util.Scanner;

public class Main{
    public static void main(String[]argc){
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] A = new int[N];
        for(int i=0;i<N;i++){
            A[i] = sc.nextInt();
        }
        int count=0;
        for(int j=0;j<N;j++){
            int min = j;
            for(int k=j;k<N;k++){
                if(A[k]<A[min]){
                    min = k;
                }
            }
            if(j==min){
                int x = A[min];
                A[min] = A[j];
                A[j] = x;
            }
            else{
                int x = A[min];
                A[min] = A[j];
                A[j] = x;
                count++;
            }
        }
        for(int m=0;m<N;m++){
            if(m==N-1){
                System.out.printf("%d",A[m]);
            }else{
                System.out.printf("%d ",A[m]);
            }
        }
        System.out.printf("\n");
        System.out.println(count);
    }
}

