		Scanner scan=new Scanner(System.in);
		Stack S=new Stack();

		while(scan.hasNext()){
			String str=scan.next();

			if(str.charAt(0)=='+'){
				int a=S.pop();
				int b=S.pop();
				S.push(b+a);
			}
			else if(str.charAt(0)=='-'){
				int a=S.pop();
				int b=S.pop();
				S.push(b-a);
			}
			else if(str.charAt(0)=='*'){
				int a=S.pop();
				int b=S.pop();
				S.push(b*a);
			}
			else {
				S.push(Integer.parseInt(str));
			}
		}
		System.out.println(S.pop());
	}
}

