                int a=stack.pop();
                a += stack.pop();
                stack.push(a);
        }
        static void doMinus(){
                int a = 0 - stack.pop();
                a += stack.pop();
                stack.push(a);
        }
        static void doMul(){
                int a=stack.pop();
                a *= stack.pop();
                stack.push(a);
        }
        static void doPop(String i){
