import java.util.*;

public class Main{
	static int search(int[] l,int key){
		int left = 0 ;
		int right = l.length;
		int mid ;

		while(left < right){
			mid = (left + right) / 2 ;
			if(l[mid] == key){
				return mid;
			}
			else if(l[mid] < key){
				left = mid +1 ;
			}
			else if(key < l[mid]){
				right = mid;
			}
		}
		return -1 ;
	}

