			tt = t[i];
			binarySearch(0, n - 1);
		}
		System.out.println(ans);
	}

	private static void binarySearch(int startIndex, int endIndex) {
		int index = (startIndex + endIndex) / 2;
		if (s[index] == tt) {
			ans++;
			return;
		} else if (startIndex == endIndex) {
			return;
		} else if (s[index] > tt) {
			binarySearch(startIndex, index);
		} else if (s[index] < tt) {
			binarySearch(index + 1, endIndex);
		}
	}
}

