        for (int i = 0; i < num; i++) {
            sum += (double)buf[i];
        }

        return sum/(double)num;
    }
    public double calcSD(int[] buf, int num) {
        double average = calcAverage(buf, num);
        double bunsan;
        double sum = 0.0;

        for (int i = 0; i < num; i++) {
            sum += Math.pow((double)buf[i] - average, 2.0);
        }
        bunsan = sum / (double)num;
        return Math.sqrt(bunsan);
    }

