    void solve() throws IOException {
      int swap = 0;
      while (true) {        
        int x = in.nextInt();
        int y = in.nextInt();
        if (x == 0 && y == 0) break; 
        if (x > y) {
          swap = x;
          x = y;
          y = swap;
        }
        out.println(x+" "+y);        
      }
    }
