        int start = Integer.parseInt(str[0]);
        int end = Integer.parseInt(str[1]);
        int num = Integer.parseInt(str[2]);

        System.out.println(Function(start,end,num));
        sc.close();
    }

    public static int Function(int start, int end, int num){
