            if (x == 0 && y == 0 ) {
                break;
            }
            for ( int c = 0; c < y ; c++) {
                builder
                   .append(StringUtilsRepeat(str,x))
                   .append("\n");
            }
            builder.append("\n");

        }
        System.out.print(builder);

    }
    public static StringBuilder StringUtilsRepeat(String str,int x) {
        StringBuilder line = new StringBuilder();

        for ( int i = 0; i < x ; i++) {
            line.append(str);
        }
        return line;
    }
}

