		StringBuilder line = new StringBuilder();
		for (int i = 0; i < n; i++) {
			if (i % 2 == 0) {
				line.append("#");
			} else {
				line.append(".");
			}
		}
		return line.toString();
	}

	static String makeEvenLine(int n) {
		StringBuilder line = new StringBuilder();
		for (int i = 0; i < n; i++) {
			if (i % 2 == 0) {
				line.append(".");
			} else {
				line.append("#");
			}
		}
		return line.toString();
	}

}

