			String mark = sc.next();
			int num = sc.nextInt();

			if(mark.equals("S")) {
				sList.add(num);
			} else if(mark.equals("H")) {
				hList.add(num);
			} else if(mark.equals("C")) {
				cList.add(num);
			} else if(mark.equals("D")) {
				dList.add(num);
			}
		}

		for(int i = 0;i < sList.size() - 1; i++) {
