		String line = sc.nextLine();
		String[] lineArray = line.split("[\\s]+");

		int n = Integer.parseInt(lineArray[0]);
		int m = Integer.parseInt(lineArray[1]);

		int[][] array = new int[n][m];
		int[] vector = new int [m];
		long[] c = new long[n];

		for (int i = 0; i < array.length; i++) {
