            for (int j = 0; j < c; ++j) {
                input[i][j] = sc.nextInt();
            }
        }

        output = new int[r + 1][c + 1];
        int sum = 0;
        for (int i = 0; i < r; ++i) {
            for (int j = 0; j < c; ++j) {
