                sum += input[i][j];
            }
        }

        //h sum
        for (int i = 0; i < r; ++i) {
            int hsum = 0;
            for (int j = 0; j < c; ++j) {
                hsum += output[i][j];
            }
            output[i][c] = hsum;
        }

        //v sum
        for (int j = 0; j < c; ++j) {
            int vsum = 0;
            for (int i = 0; i < r; ++i) {
                vsum += output[i][j];
            }
            output[r][j] = vsum;
        }

        //sum
        output[r][c] = sum;

