  BigInteger c = new BigInteger(str[2]);
  BigInteger d = new BigInteger(str[3]);

  BigInteger amax;
  BigInteger bmax;
  BigInteger result;

  if (a.multiply(c).compareTo(a.multiply(d)) >= 1)
    amax = a.multiply(c);

  else
    amax = a.multiply(d);

  if (b.multiply(c).compareTo(b.multiply(d)) >= 1)
    bmax = b.multiply(c);

  else
    bmax = b.multiply(d);

  if (amax.compareTo(bmax) >= 1) 
    result = amax;
   else
    result = bmax;

  System.out.println(result);



}
}

