                X[i] = sc.nextInt();
                Y[i] = sc.nextInt();
            }

            int count = 0;
            for (int i = 0; i < N; i++) {
                if (X[i] * X[i] + Y[i] * Y[i] <= D * D) {
                    count++;
                }
            }

            System.out.println(count);
        }
    }
}

