    static class TaskA {
        public void call(InputReader in, PrintWriter out) {
            int n ,k  ,sum=0  ;
            n = in.nextInt();
            k = in.nextInt() ;
            int[] arr= new int[n];
            for (int i = 0; i <arr.length ; i++) {
