      // 入力
      Scanner sc = new Scanner(System.in);
      long N = sc.nextLong();

      // 命名
      StringBuilder sb = new StringBuilder();
      while(N > 26){
        int amari = (int)(N % 26);
        if(amari == 0){
          amari = 26;
          N -= 26;
        }
        String s = getChar(amari);
        sb.insert(0, s);
        N = N / 26;
      }
      String last = getChar((int)N);
      sb.insert(0, last);

      // 出力
      System.out.println(sb.toString());
    }

