    static class ForbiddenList {
        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int x = in.nextInt();
            int n = in.nextInt();

            if (n == 0) {
                out.append(String.valueOf(x));
                return;
            }

            boolean[] p = new boolean[100 + 1];
            for (int i = 0; i < n; i++) {
                int a = in.nextInt();
                p[a] = true;
            }

            int pos = 0;
