                if (0 <= minus && minus <= 100) {
                    if (!p[minus]) {
                        out.append(String.valueOf(minus));
                        return;
                    }
                }
                int plus = x + pos;
                if (0 <= plus && plus <= 100) {
                    if (!p[plus]) {
                        out.append(String.valueOf(plus));
                        return;
                    }
                }
                if (minus <= 0) {
                    out.append(String.valueOf(minus));
                    return;
                }

                if (100 < plus) {
                    out.append(String.valueOf(plus));
                    return;
                }
                pos++;
            }
        }

    }
}

