    private static long convertToLong(String s){
        long num = 0;
        for(int i=0;i<s.length();i++){
            if(s.charAt(i)>='0' && s.charAt(i)<='9'){
                num=num*10 + (s.charAt(i)-'0');
            }
        }
        return num;
    }

