public class Main {

	public static void main(String[] args) {

		FastScanner sc = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);

		int A = sc.nextInt();
		int B = sc.nextInt();
		int H = sc.nextInt();
		int M = sc.nextInt();

		double Hpy = (H * 60 + M) * 2 * Math.PI / (60 * 12);
		double Mpy = (2 * Math.PI * M) / 60;
		double sita = Hpy > Mpy ? Hpy - Mpy : Mpy - Hpy;
		sita = sita > Math.PI ? Math.PI * 2 - sita : sita;
