		long[] arr = {head, center, tail};
		Arrays.sort(arr);

		if (X <= method(arr[0])){
			System.out.println(arr[0]);
		}else if (X <= method(arr[1])){
			System.out.println(arr[1]);
		}else if (X <= method(arr[2])){
			System.out.println(arr[2]);
		}
	}
}

