            x = y;
            y = buf;
        }
        int r = 0;
        while(( r = x % y) != 0)
        {
            x = y;
            y = r;
        }

        if(y < z)
        {
            int buf = y;
            y = z;
            z = buf;
        }
        while((r = y % z) != 0)
        {
            y = z;
            z = r;
        }
        return z;
    }
}

