import java.util.*;
class Main{
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int M = sc.nextInt();
    int[] vote = new int[N];
    int sum = 0;
    for(int i=0; i<N; i++){
      int tmp = sc.nextInt();
      vote[i] = tmp;
      sum += tmp;
    }
    double AVG = sum*(1d/(4*M));
    int cnt = 0;
    for(int i=0; i<N; i++){
      if(vote[i] >= AVG){
        cnt++;
      }
    }
    if(cnt<M){
      System.out.print("No");
    }else{
      System.out.print("Yes");
    }
  }
}

import java.util.Scanner;

class Main{
  public static void main(String[] args){
    Scanner scan = new Scanner(System.in);
    int n = scan.nextInt();
    int m = scan.nextInt();
    int sum = 0;
    int count = 0;
    int[] pop = new int[n];
    for(int i = 0; i < n; i++){
      pop[i] = scan.nextInt();
    }
    for(int i = 0; i < n; i++){
      sum += pop[i];
    }
    int M = 4*m;
    //double border = sum/M;
    for(int i = 0; i<n; i++){
      if(pop[i]*M >= sum){
        count++;
      }
    }
     if(count >= m){
       System.out.println("Yes");
     }else{
       System.out.println("No");
     }
  }
}

import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner scan = new Scanner(System.in);
		int N = scan.nextInt();
		int M = scan.nextInt();
		int goods[] = new int[N];
		int popular = 0;
		int sum = 0;

		for (int i = 0; i < N; i++) {
			goods[i] = scan.nextInt();
			sum = sum + goods[i];
		}

		for (int i = 0; i < N; i++) {
			if(goods[i] >= sum * ((double) 1 / (4 * M))) {
				popular++;
			}
		}

		if (popular >= M) {
			System.out.println("Yes");
		} else {
			System.out.println("No");
		}
		scan.close();
	}
}

