				loop = false;
			}
			if(x < 0) {
				loop = false;
                x = Math.abs(x);
				if(x < pre) {
					ans = x;
				} else {
					ans = pre;
				}
			}

			pre = Math.abs(x);
		}

		System.out.println(ans);
	}
}

