	}

	private static void solve(BufferedReader reader, PrintWriter writer) throws IOException {
		String[] temp = (reader.readLine()).split(" ");
		int n = Integer.parseInt(temp[0]);
		int m = Integer.parseInt(temp[1]);
		int result = 0;
		if (n >= 2) {
			result += (n * (n - 1)) / 2;
		}
		if (m >= 2) {
			result += (m * (m - 1)) / 2;
		}
		writer.println(result);
	}
}

