    private static boolean isP(String s){
      //System.out.println(s);
        int l = 0;
        int r = s.length()-1;
        while (l <= r) {
            if (s.charAt(l) != s.charAt(r)) return false;
            l++;
            r--;
        }
        return true;

    }
