        } else if (aPriceMin < bPriceMin && bPriceMin <= aPriceMax) {
            System.out.println(bPriceMin);
        } else if (aPriceMin <= bPriceMax && bPriceMax < aPriceMax) {
            System.out.println(aPriceMin);
        } else {
            System.out.println(-1);
        }
    }

}

