    public static void main(String[] args) {
        int n = sc.nextInt();
        int[] x = new int[n];
        for(int i =0; i<n ; i++){
            x[i] = sc.nextInt();
        }

        int minX = Arrays.stream(x).min().getAsInt();
        int maxX = Arrays.stream(x).max().getAsInt();

        int minValue = Integer.MAX_VALUE;
        int[] power = new int[n];
        for(int i = minX; i <= maxX; i++){ //i是p可以选择的位置
            for(int j = 0; j<x.length; j++){ //j是x的下标
                power[j] = (x[j]-i)*(x[j]-i);
            }
            minValue = Math.min(minValue, Arrays.stream(power).sum());
        }

        System.out.println(minValue);
    }
}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		// 入力値の取得
		int N = sc.nextInt();
		int[] R = new int[N];
		for (int i = 0; i < N; i++) {
			R[i] = sc.nextInt();
		}

		// 消費する体力の総和の計算
		PriorityQueue<Integer> pq = new PriorityQueue<> ();
		for (int i = 1; i <= 100; i++) {
			int sum = 0;
			for (int j = 0; j < N; j++) {
				sum += Math.pow(R[j]-i, 2);
			}
			pq.add(sum);
		}

		// 結果の出力
		System.out.println(pq.poll());

		sc.close();
	}
}

