            strinput = reader.readLine();

        }

        String arr01[] = mylist.get(0).split(" ");

        int n = Integer.valueOf(arr01[0]);
        String s = mylist.get(1);

        int cnt = 0;

        int sposi = 0;

        while (sposi < n - 2) {

            String stemp = s.substring(sposi, sposi + 3);
            if (stemp.equals("ABC")) {
                cnt += 1;
                sposi += 3;
            } else {
                sposi += 1;
            }

        }

        System.out.println(cnt);

    }

}

