	public static long gcd(long a, long b) {
		if (a == 0 || b == 0) {
			return a + b;
		} else {
			long absA = Math.abs(a);
			long absB = Math.abs(b);
			long mx = Math.max(absA, absB);
			long mn = Math.min(absA, absB);
			return gcd(mx % mn, mn);
		}
	}

