public class Main {
    public static void main(final String[] args) {
        try (Scanner sc = new Scanner(System.in, Charset.defaultCharset().name())) {
            int diff = Integer.parseInt(sc.next());
            String text = sc.next();

            StringBuilder sb = new StringBuilder();
