            BigInteger d[] = N.divideAndRemainder(new BigInteger(Integer.toString(i)));
            if (d[1].compareTo(BigInteger.ZERO)==0) {
                System.out.println(d[0].add(N.divide(d[0])).subtract(new BigInteger("2")));
                break;
            }
        }
    }
}

