    for (int i = 1; i < N; i++) {
      if (H[i-1] - H[i] >= 0) {
        count++;
      } else {
        if (count > max) {
          max = count;
        }
        count = 0;
      }
    }
    if (count > max) {
      max = count;
    }

    System.out.println(max);
  }
}

