class Main {

    public static void main(String[] args) {
		OriginScanner os = new OriginScanner();
		PrintWriter pw = new PrintWriter(System.out);

		int a = os.nextInt();
		int b = os.nextInt();
		int c = os.nextInt();

		int diff = a - b;

		int min = Math.min(diff, c);

