    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long[] H = new long[N+1];
        for(int n=1; n<=N; n++) H[n]=sc.nextLong();

        for(int n=1; n<=N; n++){
            if(H[n-1] > H[n]) answer(false);
