    public static int[] swap(int[]a,int x,int y){
        x=Math.abs(x);
        y=Math.abs(y);
        if(a.length>x&&a.length>y){
            int po=a[x];
            a[x]=a[y];
            a[y]=po;
        }
        return a;
    }
