class Solver
{
	int totalNum,dist;

	public Solver(int N,int D)
	{
		totalNum=N;
		dist=D;
	}
	public void res()
	{
		int gap=2*dist+1;
		if(totalNum%gap==0)
			System.out.printf("%d\n",totalNum/gap);
		else
			System.out.printf("%d\n",1+totalNum/gap);
	}
