public class Main {

    public static void main(String[] args) {
    	Scanner sc = new Scanner(System.in);
    	int N = sc.nextInt();
    	int D = sc.nextInt();
    	List<int[]> order = new ArrayList<>();
    	for (int i = 0; i < N; i++) {
    		int[] map = new int[D];
    		for (int j = 0; j < D; j++) {
    			map[j] = sc.nextInt();
    		}
