      int diff =0;

      //求める答え
      int ans =0;

      //差の絶対値が最小のものを求める
      for(int i=0; i<N; i++){
      	int min = Math.abs(sum-pie[i]);

         if(i == 0 ||diff > min){
         	diff = min;//条件が合えば最小を更新する
           	ans = pie[i];
         }
      }
