 		count -= (b / c) - (a / c);
 		count -= (b / d) - (a / d);
 		if(b >= c && a % c == 0){
 			count -= 1;
 		}
 		if(b >= d && a % d == 0){
 			count -= 1;
 		}
 		long e = c;
 		long f = d;
 		if(f<e){
 			long temp = f;
 			f = e;
 			e = temp;
 		}
 		while(true){
 			if(e == 0){
 				break;
 			}
 			long x = f % e;
 			f = e;
 			e = x;
 		}
 		count += (b / (c * d / f)) - (a / (c * d / f));
 		if(b >= (c * d / f) && a % (c * d / f) == 0){
 			count += 1;
 		}

