            for (long next = now + 1; next <= Math.min(now + 2, N); next++) {
                if (!a.contains(next)) {
                    dp[(int) next] += dp[(int) now];
                    dp[(int) next] %= Main.MOD;
                }
            }
        }
        return dp[(int) N];
    }

}

