        for (int i = 1; i < ways.length; i++) {
            if (vals.contains(i)) ways[i] = 0;
            else ways[i] = (ways[i - 1] + (i - 2 >= 0 ? ways[i - 2] : 0)) % mod;
        }

        System.out.println(ways[N]);
    }

