        int A = sc.nextInt();
        int B = sc.nextInt();

        System.out.println(solve(A, B));

        sc.close();
    }

    static int solve(int A, int B) {
        return IntStream.of(A * 2 - 1, B * 2 - 1, A + B).max().getAsInt();
    }
}

