class Pair<T1,T2> {
    private T1 left;
    private T2 right;

    public Pair(T1 left, T2 right) {
        this.left = left;
        this.right = right;
    }

    public T1 getLeft() {
        return this.left;
    }

    public T2 getRight() {
        return this.right;
    }

    @Override
    public boolean equals(Object object) {
        Pair pair = (Pair)object;
        if (pair.getLeft().equals(this.getLeft())
                && pair.getRight().equals(this.getRight())) {
            return true;
        }
        return false;
    }
}

