    for (int j=1; j<10; j++) {
      for (int i=0; i<menu.size(); i++) {
        if (menu.get(i) % 10 == 0) continue;
        if (menu.get(i) % 10 < min) {
          min = menu.get(i) % 10;
          last = i;
        }
      }
    }
    for (int i=0; i<menu.size(); i++) {
      if (i == last) continue;
      double ex = Math.ceil((double)menu.get(i)/10);
      total += ex * 10;
    }
    total += menu.get(last);
    System.out.println(total);
  }
}

