		else if(0 < d && d < b && d < c && d < a && d < e) {
			SUM = A2 + B2 + C2 + D + E2;
		}
		else {
			SUM = A2 + B2 + C2 + D2 + E;
		}
		System.out.print(SUM);
	}
}

