            if(!checkSet.contains(S.substring(i, i + 1))) continue;

            int tmp = 1;

            for(int j = i + 1; j < S.length(); j++) {
                String str = S.substring(j, j + 1);
                if(!checkSet.contains(str)) break;
                tmp += 1;
            }

            if(ans < tmp) ans = tmp;

        }

        pw.print(ans);
        br.close();
        pw.close();
    }
}

