        boolean judge = false;
        Arrays.sort(L);
        int max = L[N-1];
        int total = 0;
        for (int i=0; i<L.length-1; i++) {
        	total += L[i];
        }

        if (max < total) {
        	judge = true;
        }

        return judge;
    }

    //出力
    public void show(boolean answer) {
    	if (answer) {
        	System.out.println("Yes");
        } else {
        	System.out.println("No");
        }
    }

}

