			lengthList.remove(counter - 1);

			int sum = 0;
			for (int remainLengths : lengthList) {
				sum += remainLengths;
			}

			if (longestLength < sum) {
				System.out.println("Yes");
			} else {
				System.out.println("No");
			}

		} catch(Exception e) {
			System.out.println("Exception thrown : " + e);
		}
	}
}

