        for(int i=0;i<m;i++)
            if(all[i][0] == x || all[i][0] == y || all[i][1] == x || all[i][1] == y)
                continue;
            else
                return i;
        return -1;
    }

    // solution
    public static int log2(int x)
    {
        return (int) (Math.log(x) / Math.log(2));
    }

