class Main {
    public static int frog(int[] h, int n, int k) {
    	int[] dp = new int[n];

    	for(int i = 1; i < n; i++) {
    		dp[i] = dp[i-1] + Math.abs(h[i] - h[i-1]);
    		for(int j = 2; j <= k; j++) {
    			if(j > i) break;
    			dp[i] = Math.min(dp[i], dp[i-j] + Math.abs(h[i] - h[i-j]));
    		}
    	}

    	return dp[n-1];
    }

    public static void main(String[] args) {
