	public static boolean kaburi(String[] W) {
		for (int i = 0; i < W.length-1; i++) {
			for (int j = i+1; j < W.length; j++) {
				if (W[i].equals(W[j])) {
					return true;
				}
			}
		}
		return false;
	}
}

