	}

	private static boolean isLowersOtherThanAC(String S, int indexOfC) {
		char[] array = S.toCharArray();
		int length = array.length;
		for (int i = 1; i < length; i++) {
			if (i != indexOfC && Character.isUpperCase(array[i])) {
				return false;
			}
		}
		return true;
	}
}

