        for (int i = 2; i < str.length - 1; i++) {
            if ("C".equals(str[i])) {
                cCount++;
            }
        }
        return cCount == 1;
    }

    private static boolean isLowerCaseWoAAndC(String s) {
        String[] str = s.split("");
        for (int i = 1; i < str.length; i++) {
            if ("C".equals(str[i])) {
                continue;
            }
            if (str[i].equals(str[i].toUpperCase())) {
                return false;
            }
        }
        return true;
    }

