			}

			int countBig = 0;
			for (int i = 1; i < S.length(); i++) {
				if (S.charAt(i) < 'a' || 'z' < S.charAt(i)) {
					countBig++;
				}
			}
			if (countBig == 1) {
				ans3 = true;
			}

			if (ans1 && ans2 && ans3) {
				out.println("AC");
			} else {
				out.println("WA");
			}

		}
