public class Main {

	public static void main(String[] args) {

		InputScanner in = new InputScanner(System.in);
		PrintWriter out = new PrintWriter(System.out);

		int N = in.nextInt();
		int[] A = in.nextIntArray(N);

		int ans = 0;
		for (int i = 0; i < N - 1; i++) {
			for (int j = i + 1; j < N; j++) {
				int diff = Math.abs(A[i] - A[j]);
				ans = Math.max(ans, diff);
			}
		}

		out.println(ans);

		in.close();
		out.close();

	}

