	static int dev(int[] a,int an){
		boolean flg = false;
		for(int i = 0;i < a.length;i++){
			if(a[i]%2 == 0){
				flg = true;
				a[i] /= 2;
				an++;
				break;
			}
		}
		if(flg)
			return dev(a,an);
		else
