        int answer = 0;
        for (int i = 0; i < a.length; i++) {
            answer += sub(a[i]);
        }
        return answer;
    }
    public static long sub(long x) {
        int count = 0;
        while (x % 2 == 0) {
            count += 1;
            x /= 2;
        }
        return count;
    }
