        PriorityQueue<Long> numbers = new PriorityQueue<>(3,Collections.<Long>reverseOrder());
        for (int i = 0; i < 3; i++) {
            numbers.add(scanner.nextLong());
        }
        int k = scanner.nextInt();

        for (int i = 0; i < k; i++) {
