			int compare = 0;
			if (X > Y) {
				compare = X * C * 2;
			} else {
				compare = Y * C * 2;
			}
			// 上記の計算結果のほうが安い場合はそちらを採用
			if (sum > compare) {
				sum = compare;
			}

