			remain = A;
		} else {
			remain = B;
		}

		if (A >= 2 * C && B >= 2 * C) {//Its cheaper to buy AB pizza
			total = total + max * 2 * C;
		} else if (A >= 2 * C && A + B >= 2 * C && remain == A) {
			total = total + max * 2 * C;
		} else if (B >= 2 * C && A + B >= 2 * C && remain == B) {
			total = total + max * 2 * C;
		} else if (A + B >= 2 * C) {
			total = total + min * 2 * C + remain * (max - min);
		} else {
			total = A * X + B * Y;
		}
