        if(N % 2 == 0) {
        	for(int i = N - 1; i >= 0; i -= 2) {
        		alice += x[i];
        		bob += x[i - 1];
        	}
        }
        if(N % 2 != 0) {
        	if(N == 1) alice += x[0];
        	else {
				for(int i = 0; i < N; i += 2)
					alice += x[i];
				for(int i = 1; i < N; i += 2)
					bob += x[i];
			}
        }

        System.out.println(alice - bob);
	}

