        int Alice = 0;
        int Bob = 0;

        Arrays.sort(a, Comparator.reverseOrder());

        for(int i = 0; i < a.length; i++){
            if(i % 2 == 0){
                Alice += a[i];
            }else{
                Bob += a[i];
            }
        }
		return Alice - Bob;
    }
}

