	private static void dfs(int x, int y, int score) {
		if (x == n - 1 && y == 1) {
			scores.add(score);
			return;
		}

		try {
			score += a[y + 1][x];
			dfs(x, y + 1, score);
			score -= a[y + 1][x];
		} catch (Exception e) {

		}
		try {
			score += a[y][x + 1];
			dfs(x + 1, y, score);
		} catch (Exception e) {

		}

	}
}

