            int[][] map = new int[2][n];
            int max = 0;
            for (int i = 0; i < 2; i++) {
                for (int j = 0; j < n; j++) {
                    map[i][j] = in.nextInt();
                }
            }

            int prev = Arrays.stream(map[1]).sum();
            prev += map[0][0];
            max = prev;
            for (int i = 1; i < n; i++) {
                int tmp = prev;
                tmp += map[0][i] - map[1][i - 1];
                max = Math.max(max, tmp);
                prev = tmp;
            }

            out.print(max);

        }

    }
}

