            if(a <= sum && sum <= b){
                ans += i;
            }
        }
        System.out.println(ans);
    }

    public static int sumDigit(char[] c){
        int ret = 0;
        int len = c.length;
        for(int i = 0; i < len; i++){
            ret += Character.getNumericValue(c[i]);
        }
        return ret;
    }
}

