		//カウント変数
		int countNum = 0;
		boolean flagNum = true;

		do {
			for(int i = 0; i < numArray.length; i++) {
				//全て偶数か判定
				if(!(numArray[i]%2 == 0)){
					flagNum = false;
					break;
				}
				//割る２する処理を流す。
				numArray[i] = numArray[i] / 2;
			}
			//全体の処理をカウント
			if(flagNum) {
				countNum++;
			}
		}while(flagNum);//全て偶数なら繰り返す
			//標準出力
			System.out.print(countNum);
	}
}

