        for(int i = 0; i<4; i++){
            a[i] = Integer.parseInt(s.substring(i,i+1));
        }
        boolean check = true;
        for(int i = 0; i<2; i++){
            for(int j = 0; j<2; j++){
                for(int k = 0; k<2; k++){
                    int sum = a[0];
                    String[] c = new String[3];
                    if(i==0){
                        sum += a[1];
                        c[0] = "+";
                    }
                    else{
                        sum -= a[1];
                        c[0] = "-";
                    }
                    if(j==0){
                        sum += a[2];
                        c[1] = "+";
                    }
                    else{
                        sum -= a[2];
                        c[1] = "-";
                    }if(k==0){
                        sum += a[3];
                        c[2] = "+";
                    }
                    else{
                        sum -= a[3];
                        c[2] = "-";
                    }
                    if(sum==7){
                        out.println(a[0] + c[0] + a[1] + c[1] + a[2] + c[2] + a[3]+"=7");
                        check = false;
                        break;
                    }
                }
                if(!check) break;
            }
            if(!check) break;
        }
        out.close();
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (Exception e) {
                e.printStackTrace();
            }
            return null;
        }

        public boolean hasNext() {
            String next = null;
            try {
                next = reader.readLine();
            } catch (Exception e) {
            }
            if (next == null) {
                return false;
            }
            tokenizer = new StringTokenizer(next);
            return true;
        }

        public BigInteger nextBigInteger() {
            return new BigInteger(next());
        }
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
        int a = Character.getNumericValue(s.charAt(0));
        int b = Character.getNumericValue(s.charAt(1));
        int c = Character.getNumericValue(s.charAt(2));
        int d = Character.getNumericValue(s.charAt(3));

        boolean solved = false;
        for (OP op1 : OP.values()) {
            for (OP op2 : OP.values()) {
                for (OP op3 : OP.values()) {
                    int total = a;
                    total = calc(total, b, op1);
                    total = calc(total, c, op2);
                    total = calc(total, d, op3);
                    if (!solved && total == 7) {
                        System.out.println(a + op1.symbol + b + op2.symbol + c + op3.symbol + d + "=7");
                        solved = true;
                    }
                }
            }
        }
    }

    static int calc(int m, int n, OP op) {
        return op == OP.PLUS ? m + n : m - n;
    }

    enum OP {
        PLUS("+"),
        MINUS("-");

        private String symbol;
        OP(String symbol) {
            this.symbol = symbol;
        }
    }
}

