    private static boolean dfs(int[] a, String[] op, int n) {
        int sum = 0;
        if (n == 3) {
            sum = sumsub(op[0], a[0], a[1]);
            sum = sumsub(op[1], sum, a[2]);
            sum = sumsub(op[2], sum, a[3]);
            return sum == 7;
        }
        op[n] = "+";
        if (dfs(a, op,n + 1)) {
            return true;
        }
        op[n] = "-";
        if (dfs(a, op,n + 1)) {
            return true;
        }
