            for (char ch : b.toCharArray()) {
                listB.add(ch);
            }
            for (char ch : c.toCharArray()) {
                listC.add(ch);
            }
            char s = (listA.isEmpty()) ? 'a' : listA.remove(0);
            while (true) {
                switch (s) {
                    case 'a': {
                        if (listA.isEmpty()) {
                            out.println("A");
