		String N = br.readLine();

		String[] str = N.split("");

		for(int i=0; i<str.length; i++){
			if(strCnt(str, str[i])%2 != 0){
				System.out.println("No");
				return;
			}
		}
		System.out.println("Yes");
	}

	static int strCnt(String[] str, String x){
		int cnt=0;
		for(int i=0; i<str.length; i++){
			if(str[i].equals(x)){
				cnt++;
			}
		}
		return cnt;
	}
}

