			for (int j = data.length -1; i < j; j--) {
				if(0 >data[j].compareTo(data[j -1])){
					data = change(data, j, j-1);
				}
			}
	}
		StringBuilder str = new StringBuilder();
		for (String s : data) {
			str.append(s);
		}

		System.out.println(str);
		sc.close();
	}
	static String[] change(String[] s, int a, int b){
		String temp;
			temp = s[a];
			s[a] = s[b];
			s[b] = temp;
		return s;
	}
}

